insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-278', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'Neon has both a very small covalent radius and the highest first ionisation enthalpy of', '["period 3","period 2","the alkali metals","the lanthanoids"]'::jsonb, 1, 'Closed-shell compactness and maximum Zeff in that row make Ne the extreme of both trends.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'periodic-trends-general') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
