insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-279', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'From lithium to caesium, ionisation enthalpy falls while atomic radius rises, so the two trends reinforce the', '["decrease in metallic character","increase in metallic character","rise of electronegativity","formation of noble gases"]'::jsonb, 1, 'A larger, more loosely held ns¹ electron makes the heavier alkali metal more metallic.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'periodic-trends-general') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
