insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-pe-282', 'chemistry-classification-of-elements-and-periodicity-in-properties', 'chemistry', 'The first ionisation enthalpy of gallium is slightly higher than that of aluminium because the poorly shielding 3d¹⁰ electrons', '["lower Zeff on Ga","raise Zeff on Ga","remove the 4p electron","turn Ga into an alkali metal"]'::jsonb, 1, 'd-block contraction increases Zeff and offsets the expected fall of IE down group 13.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'medium', 'periodic-trends-general') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
